"""Add scores and score configs, and mark the traces that have scores.

Revision ID: 0502
Revises: 0501
Create Date: 2026-10-10

A score is one named judgement about a trace (or one of its spans): a number, a category or a
yes/no, from the API, a person or an evaluator. A score config says what a name means in a
project: its type and the values it allows. A score whose name has no config creates one with
the type the score implies (`implicit`); a config made or edited in the dashboard is explicit.

Choices worth knowing about:

* Ids are UUIDv7 generated by the application (or by the client, for a score it may retry), so
  the columns have no default.
* The `scores` primary key is `(project_id, id)`, not `id` alone. Clients supply score ids so a
  retried batch is idempotent (`ON CONFLICT DO NOTHING`). With a global key, a score whose id
  another tenant happened to use would conflict with a row row-level security hides, and be
  dropped without a word.
* `data_type` is an enum shared by both tables. CHECKs keep each score's value columns in step
  with its type: numeric has `value` only, boolean has `value` 0 or 1 only, categorical has
  `string_value` only. A config's bounds match its type too: a range only for numeric,
  categories only for categorical, neither for boolean.
* `trace_id` is not a foreign key: a score may arrive before its trace. `span_id` is free text
  for the same reason.
* `evaluator_run_id` is a plain uuid here; its foreign key (`ON DELETE SET NULL`) comes with the
  evaluator runs table in 0505. `author_user_id` is `ON DELETE SET NULL`, so deleting a user keeps
  their scores, and indexed (partially) so that delete does not scan the table.
* Indexes: `(project_id, trace_id)` for a trace's scores, `(project_id, name, created_at DESC)`
  for a name's history and the config-in-use check. `UNIQUE (project_id, name)` on configs. A
  BRIN index on `created_at` serves the worker's sweep over recent scores across projects
  (scores are appended in time order, so the BRIN index is tiny and cheap to maintain).
* Row-level security on both tables is the policy pair every project-scoped table has, in the
  InitPlan form of 0017.
* `traces.has_scores` is added with a constant default, which PostgreSQL 17 records in the
  catalog without rewriting the table. It still needs a brief ACCESS EXCLUSIVE lock on the
  hottest table, so, as in 0401 and 0501, it runs outside the migration's transaction with a
  5 second `lock_timeout`: the migration gives up rather than queue every ingest behind a long
  reader. The partial index `(project_id, started_at DESC) WHERE has_scores` serves the
  explorer's "has scores" filter; it is built `CONCURRENTLY` in the same autocommit block, so
  ingestion keeps writing to `traces`, and a leftover INVALID index from an interrupted build is
  dropped first (as in 0302).
* The autocommit block commits the transactional part before `alembic_version` moves, so an
  interrupted run is re-run from the top. Every statement is therefore idempotent: the types are
  created in a block that ignores `duplicate_object`, tables, indexes and the column use
  `IF NOT EXISTS`, and each policy is dropped before it is created.

Downgrade drops the index (concurrently), the tables, the column (with the same lock timeout)
and the types.
"""

from collections.abc import Sequence

import sqlalchemy as sa

from alembic import op

revision: str = "0502"
down_revision: str | None = "0501"
branch_labels: str | Sequence[str] | None = None
depends_on: str | Sequence[str] | None = None

TABLES = ("scores", "score_configs")
TYPES = ("score_source", "score_data_type")
SCORED_INDEX = "traces_project_scored_started_idx"
NAME_PATTERN = "^[a-z0-9][a-z0-9_.-]{0,63}$"

PROJECT_EXPRESSION = (
    "project_id = (SELECT NULLIF(current_setting('app.project_id', true), '')::uuid)"
)
BYPASS_EXPRESSION = "(SELECT current_setting('app.bypass_rls', true)) = 'on'"
LOCK_TIMEOUT = "5s"


def upgrade() -> None:
    _create_type("score_data_type", "'numeric', 'categorical', 'boolean'")
    _create_type("score_source", "'api', 'human', 'eval'")
    _create_score_configs()
    _create_scores()
    for table in TABLES:
        _enable_rls(table)
    _add_scored_column_and_index()


def _create_type(name: str, labels: str) -> None:
    """`CREATE TYPE` that a re-run after an interrupted migration skips."""
    op.execute(
        f"DO $$ BEGIN CREATE TYPE {name} AS ENUM ({labels}); "
        "EXCEPTION WHEN duplicate_object THEN NULL; END $$"
    )


def _create_score_configs() -> None:
    op.execute(
        f"""
        CREATE TABLE IF NOT EXISTS score_configs (
            id           uuid PRIMARY KEY,
            project_id   uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
            name         text NOT NULL CHECK (name ~ '{NAME_PATTERN}'),
            data_type    score_data_type NOT NULL,
            min_value    numeric(14, 4),
            max_value    numeric(14, 4),
            categories   text[] NOT NULL DEFAULT '{{}}' CHECK (cardinality(categories) <= 100),
            description  text CHECK (char_length(description) <= 500),
            implicit     boolean NOT NULL DEFAULT true,
            created_at   timestamptz NOT NULL DEFAULT now(),
            updated_at   timestamptz NOT NULL DEFAULT now(),
            CONSTRAINT score_configs_project_name_key UNIQUE (project_id, name),
            CONSTRAINT score_configs_range_order
                CHECK (min_value IS NULL OR max_value IS NULL OR min_value <= max_value),
            CONSTRAINT score_configs_bounds_for_type CHECK (
                CASE data_type
                    WHEN 'numeric' THEN cardinality(categories) = 0
                    WHEN 'categorical' THEN min_value IS NULL AND max_value IS NULL
                    ELSE min_value IS NULL AND max_value IS NULL
                        AND cardinality(categories) = 0
                END
            )
        )
        """
    )


def _create_scores() -> None:
    op.execute(
        f"""
        CREATE TABLE IF NOT EXISTS scores (
            id                uuid NOT NULL,
            project_id        uuid NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
            trace_id          text NOT NULL CHECK (trace_id ~ '^[0-9a-f]{{32}}$'),
            span_id           text CHECK (char_length(span_id) BETWEEN 1 AND 64),
            name              text NOT NULL CHECK (name ~ '{NAME_PATTERN}'),
            data_type         score_data_type NOT NULL,
            value             numeric(14, 4),
            string_value      text CHECK (char_length(string_value) BETWEEN 1 AND 200),
            source            score_source NOT NULL,
            comment           text CHECK (char_length(comment) <= 2000),
            author_user_id    uuid REFERENCES users (id) ON DELETE SET NULL,
            evaluator_run_id  uuid,
            created_at        timestamptz NOT NULL DEFAULT now(),
            CONSTRAINT scores_pkey PRIMARY KEY (project_id, id),
            CONSTRAINT scores_value_for_type CHECK (
                CASE data_type
                    WHEN 'numeric' THEN value IS NOT NULL AND string_value IS NULL
                    WHEN 'boolean' THEN value IS NOT NULL AND value IN (0, 1)
                        AND string_value IS NULL
                    ELSE string_value IS NOT NULL AND value IS NULL
                END
            )
        )
        """
    )
    op.execute(
        "CREATE INDEX IF NOT EXISTS scores_project_trace_idx ON scores (project_id, trace_id)"
    )
    op.execute(
        "CREATE INDEX IF NOT EXISTS scores_project_name_created_idx "
        "ON scores (project_id, name, created_at DESC)"
    )
    op.execute(
        "CREATE INDEX IF NOT EXISTS scores_author_user_idx ON scores (author_user_id) "
        "WHERE author_user_id IS NOT NULL"
    )
    op.execute(
        "CREATE INDEX IF NOT EXISTS scores_evaluator_run_idx ON scores (evaluator_run_id) "
        "WHERE evaluator_run_id IS NOT NULL"
    )
    op.execute(
        "CREATE INDEX IF NOT EXISTS scores_created_brin_idx ON scores USING brin (created_at)"
    )


def _enable_rls(table: str) -> None:
    op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
    op.execute(f"ALTER TABLE {table} FORCE ROW LEVEL SECURITY")
    op.execute(f"DROP POLICY IF EXISTS {table}_project_isolation ON {table}")
    op.execute(f"DROP POLICY IF EXISTS {table}_worker_bypass ON {table}")
    op.execute(
        f"CREATE POLICY {table}_project_isolation ON {table} "
        f"USING ({PROJECT_EXPRESSION}) WITH CHECK ({PROJECT_EXPRESSION})"
    )
    op.execute(
        f"CREATE POLICY {table}_worker_bypass ON {table} "
        f"USING ({BYPASS_EXPRESSION}) WITH CHECK ({BYPASS_EXPRESSION})"
    )


def _index_is_valid(name: str) -> bool | None:
    """True if the index exists and is valid, False if it exists but is INVALID, None if absent.

    Offline (`--sql`) there is no database to ask, so the answer is None and the statements below
    are the unconditional ones.
    """
    context = op.get_context()
    if context.as_sql:
        return None
    row = context.bind.execute(  # type: ignore[union-attr]  # bind is set when not as_sql
        sa.text(
            "SELECT i.indisvalid FROM pg_index AS i JOIN pg_class AS c ON c.oid = i.indexrelid "
            "WHERE c.relname = :name AND c.relnamespace = current_schema()::regnamespace"
        ),
        {"name": name},
    ).first()
    return None if row is None else bool(row[0])


def _add_scored_column_and_index() -> None:
    with op.get_context().autocommit_block():
        # The ALTER needs ACCESS EXCLUSIVE on `traces`: give up rather than queue every ingest
        # write behind a long transaction.
        op.execute(f"SET lock_timeout = '{LOCK_TIMEOUT}'")
        op.execute(
            "ALTER TABLE traces ADD COLUMN IF NOT EXISTS has_scores boolean NOT NULL DEFAULT false"
        )
        op.execute("RESET lock_timeout")
        state = _index_is_valid(SCORED_INDEX)
        if state is True:
            return
        if state is False:
            op.execute(f"DROP INDEX CONCURRENTLY IF EXISTS {SCORED_INDEX}")
        op.execute(
            f"CREATE INDEX CONCURRENTLY {SCORED_INDEX} "
            "ON traces (project_id, started_at DESC) WHERE has_scores"
        )


def downgrade() -> None:
    with op.get_context().autocommit_block():
        op.execute(f"DROP INDEX CONCURRENTLY IF EXISTS {SCORED_INDEX}")
        op.execute(f"SET lock_timeout = '{LOCK_TIMEOUT}'")
        op.execute("ALTER TABLE traces DROP COLUMN IF EXISTS has_scores")
        op.execute("RESET lock_timeout")
    for table in TABLES:
        op.execute(f"DROP TABLE IF EXISTS {table}")
    for type_name in TYPES:
        op.execute(f"DROP TYPE IF EXISTS {type_name}")
